except ValueError as e:
    print(e)

try:
    print(unpad('Short'))  # Should return 'Short' since it has no padding
except ValueError as e:
    print(e)

try:
    print(unpad('A' * 15 + '\x01'))  # Should output 'A' * 15
except ValueError as e:
    print(e)

try:
