        btnUp.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                executeSSHCommand();
            }
        });
    }

    private void executeSSHCommand() {
        // Using HandlerThread to run the task in the background
        HandlerThread handlerThread = new HandlerThread("SSHCommandExecutor");
        handlerThread.start();
        final Handler handler = new Handler(handlerThread.getLooper());
        handler.post(new Runnable() {
            @Override
            public void run() {
                runSSHCommand();
            }
        });
    }

    private void runSSHCommand() {
        try {
            JSch jsch = new JSch();
            // Load the private key from a secure location on the Android device
            jsch.addIdentity("/path/to/private/key");

            Session session = jsch.getSession("pi", wifiModuleIp, wifiModulePort);

            // Avoid asking for key confirmation
            session.setConfig("StrictHostKeyChecking", "no");

            session.connect();

            // Start the channel
            Channel channel = session.openChannel("exec");
            ((ChannelExec) channel).setCommand(CMD);

            // Get the output stream to write to the remote command
            InputStream in = channel.getInputStream();
            OutputStream out = channel.getOutputStream();

            channel.connect();

            // Write the command to the remote command
            out.write((CMD + "\n").getBytes());

            // Read the response
            byte[] tmp = new byte[1024];
            while (true) {
                while (in.available() > 0) {
                    int i = in.read(tmp, 0, 1024);
                    if (i < 0) break;
                    System.out.print(new String(tmp, 0, i));
                }
                if (channel.isClosed()) {
                    System.out.println("exit-status: " + channel.getExitStatus());
                    break;
                }
                try { Thread.sleep(1000); } catch (Exception ee) {}
            }

            channel.disconnect();
            session.disconnect();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

### Security Best Practices:
1. **Use Key-Based Authentication:** Instead of storing passwords in plain text, use key-based authentication by loading the private key from a secure location on the Android device.
2. **Restrict SSH Access:** Configure the SSH server on the Raspberry Pi to restrict access to specific users or groups and disable root login directly over SSH.
3. **Limit Command Execution:** Restrict the commands that can be executed remotely to only those necessary for your application.
4. **Encrypt Communication:** Ensure that all communication between the Android app and the Raspberry Pi is encrypted using SSH.
5. **Monitor and Log:** Implement logging on both the Android app and the Raspberry Pi to monitor for unauthorized access attempts and suspicious activities.

By using a `HandlerThread` for background operations, this solution remains compatible across various Android versions, including those before and after API level 30.

To fix the column reordering logic to ensure it works with a list instead of a set for `reference_columns`, and to optimize the `read_pdf` function using multiprocessing for handling large datasets or a large number of files more efficiently, the following improvements are made:

```python
import os
import re
import sys
import pandas as pd
from tabula import read_pdf
from concurrent.futures import ProcessPoolExecutor


def check_column_consistency(directory):
    reference_columns = None
    for filename in os.listdir(directory):
        if filename.endswith(".pdf"):
            file_path = os.path.join(directory, filename)
            try:
                df = read_pdf(file_path, pages='all', pandas_options={'header': [0]})
                if reference_columns is None:
                    reference_columns = df.columns.tolist()
                elif df.columns.tolist() != reference_columns:
                    raise ValueError(f"Inconsistent columns found in {filename}.")
            except Exception as e:
                print(f"Failed to process {filename} during initial check: {e}")
    return reference_columns

def process_pdf_file(file_path, reference_columns):
    try:
        df = read_pdf(file_path, pages='all', pandas_options={'header': [0]}, multiple_tables=False)
        if 'Date' in df.columns:
            df.rename(columns={'Date': 'Posted Date'}, inplace=True)
        if 'Desc' in df.columns:
            df.rename(columns={'Desc': 'Description'}, inplace=True)
        if set(df.columns) != set(reference_columns):
            raise ValueError(f"Column mismatch in {file_path}.")
        df = df[reference_columns]
        return df
    except Exception as e:
        print(f"Failed to process {file_path}: {e}")
        return None

def process_pdf_files(directory, reference_columns, chunk_size=10):
    all_dataframes = []
    pdf_files = [os.path.join(directory, f) for f in os.listdir(directory) if f.endswith(".pdf")]
    with ProcessPoolExecutor() as executor:
        results = list(executor.map(lambda file: process_pdf_file(file, reference_columns), pdf_files))
    for df in results:
        if df is not None:
            all_dataframes.append(df)
    if not all_dataframes:
        raise FileNotFoundError("No valid PDF files found in the directory.")
    combined_df = pd.concat(all_dataframes, ignore_index=True)
    return combined_df

def validate_columns(df):
    if 'Posted Date' not in df.columns or 'Description' not in df.columns:
        raise ValueError("Required columns 'Posted Date' and 'Description' do not exist.")
    try:
        df['Posted Date'] = pd.to_datetime(df['Posted Date'], errors='raise')
    except ValueError as e:
        raise ValueError(f"Invalid date format in 'Posted Date' column: {e}")

def filter_and_sort_data(df):
    validate_columns(df)
    pattern = r"NWAUKWA I.C|NWAUKWA STEPHEN|NWAUKWA ISAAC|ISAAC NWAUKWA|CHINEDU|chinedu"
    filtered_df = df[df['Description'].str.contains(pattern, case=False)]
    sorted_df = filtered_df.sort_values(by='Posted Date')
    return sorted_df

def main():
    if len(sys.argv) < 2:
        print("Usage: python script.py <directory>")
        sys.exit(1)
    directory = sys.argv[1]
    try:
        reference_columns = check_column_consistency(directory)
        combined_df = process_pdf_files(directory, reference_columns)
        sorted_df = filter_and_sort_data(combined_df)
        sorted_df.to_csv('combined_sorted.csv', index=False, columns=['Posted Date', 'Description', 'Debit', 'Credit', 'Balance'])
        print("CSV file generated successfully.")
    except FileNotFoundError as e:
        print(e)
    except ValueError as e:
        print(e)

if __name__ == "__main__":
    main()
```
This script ensures that all PDF files have consistent columns, handles cases where columns are missing or need reordering, and optimizes the processing and concatenation of DataFrames using multiprocessing to handle large datasets more efficiently.

To enhance the visual interface of the chess application, we'll consider the following aspects:

1. **Game Board Visualization**: The game board will be displayed as an 8x8 grid, with each cell either colored light or dark to represent the alternating squares of the chessboard. Chess pieces will be represented by icons or images placed on the appropriate cells.

2. **Settings Panel**: The settings panel will appear when a specific button is clicked. It will allow users to input player names and choose options such as time controls for the game. Once the settings are configured, they can be applied to the game.

3. **Design Pattern**: The Observer pattern will be used to ensure that the visual interface updates in response to changes in the game state, such as a move being made. This pattern helps in maintaining a clean separation of concerns, making the application easier to manage and extend.

Below is a simplified C++ example, which demonstrates how the game board and settings panel might be implemented, along with the Observer pattern.

```cpp
#include <iostream>
#include <memory>
#include <string>

// Observer Pattern Example

// Subject Interface
class Subject {
public:
    virtual ~Subject() {}
    virtual void attach(Observer*) = 0;
    virtual void detach(Observer*) = 0;
    virtual void notify() = 0;
};

// Observer Interface
class Observer {
public:
    virtual ~Observer() {}
    virtual void update() = 0;
};

// Concrete Subject
class GameBoard : public Subject {
private:
    std::vector<Observer*> observers;
public:
    void attach(Observer* observer) override {
        observers.push_back(observer);
    }
    void detach(Observer* observer) override {
        observers.erase(std::remove(observers.begin(), observers.end(), observer), observers.end());
    }
    void notify() override {
        for (auto* observer : observers) {
            observer->update();
        }
    }
    void makeMove(int x, int y) {
        // Simulate a move
        notify();
    }
};

// Concrete Observer
class GameView : public Observer {
public:
    void update() override {
        std::cout << "Game view updated.\n";
    }
};

int main() {
    GameBoard board;
    GameView view1, view2;
    board.attach(&view1);
    board.attach(&view2);
    board.makeMove(3, 3);
    board.detach(&view2);
    board.makeMove(5, 5);
    return 0;
}
```

### Explanation

- **GameBoard**: This class represents the subject in the Observer pattern, notifying the observers whenever a move is made.
- **GameView**: This class acts as the observer, updating itself in response to notifications from the game board.

In this setup, the Observer pattern ensures that the visual interface updates in response to changes in the game state, keeping the application consistent and responsive.

